const updateInstance = `-- name: UpdateInstance :execrows
UPDATE process_instances
SET task             = ?1,
    next_replayable   = ?2,
    task_epoch       = ?3,
    outputs_data     = ?4,
    output_data      = ?5,
    error_internal   = ?6,
    error_data       = ?7,
    external_input   = ?8,
    external_lost    = ?9,
    engine_state     = ?10,
    objects          = ?11,
    retry_count      = ?12,
    wake_at    = ?13,
    status           = CASE WHEN status = 'pausing'
                            AND CAST(?14 AS TEXT) = 'running'
                            THEN 'paused'
                            WHEN status = 'cancelling'
                            AND CAST(?14 AS TEXT) = 'running'
                            THEN 'cancelled' ELSE CAST(?14 AS TEXT) END,
    phase       = ?15,
    error_message    = ?16,
    error_code       = ?17,
    updated_at       = ?18,
    external_worker_id        = CASE WHEN task_epoch = ?3 THEN external_worker_id END,
    external_lease_expires_at = CASE WHEN task_epoch = ?3 THEN external_lease_expires_at END,
    worker_id        = NULL,
    lease_expires_at = NULL
WHERE id = ?19 AND lease_epoch = ?20
  AND COALESCE(worker_id, '') = CAST(?21 AS TEXT)
`

type UpdateInstanceParams struct {
	Task           string
	NextReplayable int64
	TaskEpoch      int64
	OutputsData    string
	OutputData     string
	ErrorInternal  string
	ErrorData      string
	ExternalInput  string
	ExternalLost   int64
	EngineState    string
	Objects        string
	RetryCount     int64
	WakeAt         sql.NullInt64
	Status         string
	Phase          string
	ErrorMessage   string
	ErrorCode      string
	UpdatedAt      int64
	ID             string
	LeaseEpoch     int64
	WorkerID       string
}

// input_data is never written. The status CASE lands a pause/cancel that arrived mid-lease;
// moving task_epoch drops the external claim. Fence: CLAUDE.md, the lease fence -- COALESCE
// so a lease-less caller's unheld row still matches.
func (q *Queries) UpdateInstance(ctx context.Context, arg UpdateInstanceParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateInstance,
		arg.Task,
		arg.NextReplayable,
		arg.TaskEpoch,
		arg.OutputsData,
		arg.OutputData,
		arg.ErrorInternal,
		arg.ErrorData,
		arg.ExternalInput,
		arg.ExternalLost,
		arg.EngineState,
		arg.Objects,
		arg.RetryCount,
		arg.WakeAt,
		arg.Status,
		arg.Phase,
		arg.ErrorMessage,
		arg.ErrorCode,
		arg.UpdatedAt,
		arg.ID,
		arg.LeaseEpoch,
		arg.WorkerID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

