const upgradeInstanceVersion = `-- name: UpgradeInstanceVersion :execrows
UPDATE process_instances
SET process_version = ?1,
    input_data      = ?2,
    outputs_data    = ?3,
    output_data     = ?4,
    error_internal  = ?5,
    error_data      = ?6,
    external_input  = ?7,
    external_lost   = ?8,
    engine_state    = ?9,
    objects         = ?10,
    updated_at      = ?11
WHERE id = ?12
  AND process_version = ?13
  AND task = ?14
  AND status IN ('paused', 'failed')
  AND worker_id IS NULL
`

type UpgradeInstanceVersionParams struct {
	ToVersion     int64
	InputData     string
	OutputsData   string
	OutputData    string
	ErrorInternal string
	ErrorData     string
	ExternalInput string
	ExternalLost  int64
	EngineState   string
	Objects       string
	UpdatedAt     int64
	ID            string
	FromVersion   int64
	Task          string
}

// Every predicate pins what the state was conformed against, so a stale move loses the race
// instead of clobbering (specs/version-compatibility.md s4). Never clear worker_id to admit a
// move: it is the only_once evidence.
func (q *Queries) UpgradeInstanceVersion(ctx context.Context, arg UpgradeInstanceVersionParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, upgradeInstanceVersion,
		arg.ToVersion,
		arg.InputData,
		arg.OutputsData,
		arg.OutputData,
		arg.ErrorInternal,
		arg.ErrorData,
		arg.ExternalInput,
		arg.ExternalLost,
		arg.EngineState,
		arg.Objects,
		arg.UpdatedAt,
		arg.ID,
		arg.FromVersion,
		arg.Task,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const upsertChannel = `-- name: UpsertChannel :exec
INSERT INTO process_channels (name, channel, version, updated_at, actor)
VALUES (?1, ?2, ?3, ?4, ?5)
ON CONFLICT (name, channel) DO UPDATE SET
    version = EXCLUDED.version, updated_at = EXCLUDED.updated_at, actor = EXCLUDED.actor
`

type UpsertChannelParams struct {
	Name      string
	Channel   string
	Version   int64
	UpdatedAt int64
	Actor     string
}

// Overwrites actor, unlike InsertDefinition: a channel is a mutable pointer, so the actor is
// whoever moved it last.
func (q *Queries) UpsertChannel(ctx context.Context, arg UpsertChannelParams) error {
	_, err := q.db.ExecContext(ctx, upsertChannel,
		arg.Name,
		arg.Channel,
		arg.Version,
		arg.UpdatedAt,
		arg.Actor,
	)
	return err
}

const wakeParent = `-- name: WakeParent :exec
UPDATE process_instances
SET phase = CASE WHEN status IN ('running', 'pausing', 'paused')
                      THEN 'collecting' ELSE '' END,
    updated_at = ?1
WHERE id = ?2
`

type WakeParentParams struct {
	UpdatedAt int64
	ID        string
}

// A paused parent is armed too (suspended, not doomed); its status keeps it unclaimable.
func (q *Queries) WakeParent(ctx context.Context, arg WakeParentParams) error {
	_, err := q.db.ExecContext(ctx, wakeParent, arg.UpdatedAt, arg.ID)
	return err
}
